BEGIN TRANSACTION;
CREATE TABLE "directory_adminscope" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "application" varchar(30) NOT NULL, "resource_type" varchar(80) NOT NULL, "resource_id" varchar(200) NOT NULL, "allowed_roles" text NOT NULL CHECK ((JSON_VALID("allowed_roles") OR "allowed_roles" IS NULL)), "active" bool NOT NULL, "organisation_id" char(32) NOT NULL REFERENCES "directory_organisation" ("id") DEFERRABLE INITIALLY DEFERRED, "person_id" char(32) NOT NULL REFERENCES "directory_person" ("id") DEFERRABLE INITIALLY DEFERRED);
INSERT INTO "directory_adminscope" VALUES(1,'holy-sheet','tenant','00000000-0000-4000-8000-000000000002','["admin"]',1,'00000000000040008000000000000002','00000000000040008000000000000001');
CREATE TABLE "directory_applicationaccess" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "application" varchar(30) NOT NULL, "status" varchar(30) NOT NULL, "organisation_id" char(32) NOT NULL REFERENCES "directory_organisation" ("id") DEFERRABLE INITIALLY DEFERRED, "person_id" char(32) NOT NULL REFERENCES "directory_person" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "app_access_once" UNIQUE ("organisation_id", "person_id", "application"));
INSERT INTO "directory_applicationaccess" VALUES(1,'holy-sheet','active','00000000000040008000000000000002','00000000000040008000000000000001');
CREATE TABLE "directory_connectorstate" ("application" varchar(30) NOT NULL PRIMARY KEY, "mode" varchar(30) NOT NULL, "permission_contract_sha256" varchar(64) NOT NULL, "parity_verified_at" datetime NULL, "revocation_verified_at" datetime NULL, "baseline_id" bigint NOT NULL REFERENCES "directory_snapshot" ("id") DEFERRABLE INITIALLY DEFERRED);
INSERT INTO "directory_connectorstate" VALUES('holy-sheet','central','bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb','2026-10-28 06:25:56.358159','2026-10-28 06:25:56.358160',1);
CREATE TABLE "directory_externalsubject" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "issuer" varchar(200) NOT NULL, "subject" varchar(255) NOT NULL, "person_id" char(32) NOT NULL REFERENCES "directory_person" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_issuer_subject" UNIQUE ("issuer", "subject"));
INSERT INTO "directory_externalsubject" VALUES(1,'https://accounts.example.test','fixture-subject','00000000000040008000000000000001');
CREATE TABLE "directory_identityreview" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "normalized_email" varchar(320) NOT NULL UNIQUE, "status" varchar(50) NOT NULL, "reason" varchar(300) NOT NULL);
CREATE TABLE "directory_identityreview_accounts" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "identityreview_id" bigint NOT NULL REFERENCES "directory_identityreview" ("id") DEFERRABLE INITIALLY DEFERRED, "observedaccount_id" bigint NOT NULL REFERENCES "directory_observedaccount" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "directory_localaccountbinding" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "application" varchar(30) NOT NULL, "local_id" varchar(200) NOT NULL, "review_reference" varchar(300) NOT NULL, "created_at" datetime NOT NULL, "evidence_id" bigint NOT NULL REFERENCES "directory_observedaccount" ("id") DEFERRABLE INITIALLY DEFERRED, "person_id" char(32) NOT NULL REFERENCES "directory_person" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "existing_account_bound_once" UNIQUE ("application", "local_id"));
CREATE TABLE "directory_migrationevent" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "action" varchar(80) NOT NULL, "details" text NOT NULL CHECK ((JSON_VALID("details") OR "details" IS NULL)));
CREATE TABLE "directory_observedaccount" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "application" varchar(30) NOT NULL, "local_id" varchar(200) NOT NULL, "email" varchar(320) NOT NULL, "name" varchar(300) NOT NULL, "active" bool NOT NULL, "email_verified" bool NOT NULL, "local_privileges" text NOT NULL CHECK ((JSON_VALID("local_privileges") OR "local_privileges" IS NULL)), "account_kind" varchar(30) NOT NULL, "snapshot_id" bigint NOT NULL REFERENCES "directory_snapshot" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "observed_local_user_once" UNIQUE ("snapshot_id", "application", "local_id"));
CREATE TABLE "directory_organisation" ("id" char(32) NOT NULL PRIMARY KEY, "name" varchar(200) NOT NULL);
INSERT INTO "directory_organisation" VALUES('00000000000040008000000000000002','Synthetic test tenant');
CREATE TABLE "directory_organisationmember" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "status" varchar(30) NOT NULL, "organisation_id" char(32) NOT NULL REFERENCES "directory_organisation" ("id") DEFERRABLE INITIALLY DEFERRED, "person_id" char(32) NOT NULL REFERENCES "directory_person" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "organisation_member_once" UNIQUE ("organisation_id", "person_id"));
