CREATE TABLE "directory_permissionapproval" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "decision" varchar(20) NOT NULL, "note" varchar(500) NOT NULL, "created_at" datetime NOT NULL, "actor_id" char(32) NOT NULL REFERENCES "directory_person" ("id") DEFERRABLE INITIALLY DEFERRED, "change_id" char(32) NOT NULL REFERENCES "directory_permissionchange" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "one_decision_per_approver" UNIQUE ("change_id", "actor_id"));
CREATE TABLE "directory_permissionchange" ("id" char(32) NOT NULL PRIMARY KEY, "request_key" char(32) NOT NULL UNIQUE, "resource_type" varchar(80) NOT NULL, "resource_id" varchar(200) NOT NULL, "requested_role" varchar(100) NOT NULL, "expected_before_sha256" varchar(64) NOT NULL, "state" varchar(30) NOT NULL, "created_at" datetime NOT NULL, "organisation_id" char(32) NOT NULL REFERENCES "directory_organisation" ("id") DEFERRABLE INITIALLY DEFERRED, "target_id" bigint NOT NULL REFERENCES "directory_localaccountbinding" ("id") DEFERRABLE INITIALLY DEFERRED, "requested_by_id" char(32) NOT NULL REFERENCES "directory_person" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "directory_permissionevidence" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "application" varchar(30) NOT NULL, "source_table" varchar(150) NOT NULL, "row_sha256" varchar(64) NOT NULL, "ordinal" integer unsigned NOT NULL CHECK ("ordinal" >= 0), "payload" text NOT NULL CHECK ((JSON_VALID("payload") OR "payload" IS NULL)), "snapshot_id" bigint NOT NULL REFERENCES "directory_snapshot" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "permission_evidence_row_once" UNIQUE ("snapshot_id", "source_table", "ordinal"));
CREATE TABLE "directory_person" ("id" char(32) NOT NULL PRIMARY KEY, "email" varchar(254) NOT NULL UNIQUE, "status" varchar(30) NOT NULL, "created_at" datetime NOT NULL, "suite_role" varchar(30) NOT NULL);
