CREATE TABLE "directory_resourcemapping" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "application" varchar(30) NOT NULL, "resource_type" varchar(80) NOT NULL, "resource_id" varchar(200) NOT NULL, "review_reference" varchar(300) NOT NULL, "organisation_id" char(32) NOT NULL REFERENCES "directory_organisation" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "resource_organisation_once" UNIQUE ("application", "resource_type", "resource_id"));
