CREATE TABLE "directory_snapshot" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "database" varchar(100) NOT NULL, "ciphertext_sha256" varchar(64) NOT NULL UNIQUE, "captured_at" varchar(100) NOT NULL, "imported_at" datetime NOT NULL, "table_statistics" text NOT NULL CHECK ((JSON_VALID("table_statistics") OR "table_statistics" IS NULL)), "restore_verified" bool NOT NULL);
